 if(sourceCurrency!=='CNY'||targetCurrency!=='EUR')throw Error('Tigshop 必须明确配置人民币转欧元');
 if(typeof eurPerCny!=='number'||!Number.isFinite(eurPerCny)||eurPerCny<=0||eurPerCny>1)throw Error('请配置有效汇率：1 人民币对应的欧元金额');
