 return skus.map(s=>{
  if(typeof s.price!=='number'||!Number.isFinite(s.price)||s.price<=0||typeof s.cost!=='number'||!Number.isFinite(s.cost)||s.cost<0)throw Error('人民币售价或成本无效');
